import ast
import os
import shutil
import subprocess
import sys
import tempfile
import unittest

try:
    from helpers import ROOT, ShopTest
except ImportError:
    from tests.helpers import ROOT, ShopTest

try:
    import tomllib
except ImportError:
    tomllib = None

SRC_PKG = os.path.join(ROOT, "src", "stockroom")
FALLBACK_STDLIB = {"ast", "argparse", "collections", "contextlib", "dataclasses", "datetime", "decimal", "enum",
                   "functools", "io", "itertools", "json", "os", "re", "sys", "textwrap", "typing", "__future__"}
STDLIB = getattr(sys, "stdlib_module_names", FALLBACK_STDLIB)


def sources():
    for base, _, names in os.walk(SRC_PKG):
        for name in sorted(names):
            if name.endswith(".py"):
                yield os.path.join(base, name)


def run(argv, **kw):
    env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH", "PYTHONHOME", "VIRTUAL_ENV")}
    return subprocess.run(argv, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                          stderr=subprocess.STDOUT, universal_newlines=True, **kw)


class PackagingTest(ShopTest):
    def test_pyproject(self):
        with open(os.path.join(ROOT, "pyproject.toml"), "rb") as handle:
            raw = handle.read()
        if tomllib is not None:
            project = tomllib.loads(raw.decode("utf-8"))["project"]
            self.assertEqual(project["requires-python"], ">=3.9")
            self.assertEqual(project["scripts"], {"stockroom": "stockroom.cli:main"})
            self.assertEqual(project.get("dependencies", []), [])
        else:
            text = raw.decode("utf-8")
            self.assertIn('requires-python = ">=3.9"', text)
            self.assertIn('stockroom = "stockroom.cli:main"', text)
            self.assertNotRegex(text, r"dependencies\s*=\s*\[\s*[\"']")

    def test_pip_install_gives_library_and_command(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = os.path.join(tmp, "repo")
            shutil.copytree(ROOT, repo, ignore=shutil.ignore_patterns(
                ".git", ".harness*", ".claude", "build", "*.egg-info", "__pycache__", "dist"))
            venv = os.path.join(tmp, "venv")
            made = run([sys.executable, "-m", "venv", "--system-site-packages", venv])
            if made.returncode:
                self.skipTest("venv unavailable: " + made.stdout[-300:])
            bindir = os.path.join(venv, "Scripts" if os.name == "nt" else "bin")
            py = os.path.join(bindir, "python.exe" if os.name == "nt" else "python")
            probe = run([py, "-c", "import pip, setuptools"])
            if probe.returncode:
                self.skipTest("pip/setuptools unavailable in venv: " + probe.stdout[-300:])
            done = run([py, "-m", "pip", "install", "--no-build-isolation", "--no-index", "--disable-pip-version-check", repo])
            if done.returncode:
                out = done.stdout
                if any(s in out for s in ("No module named", "network", "Connection", "No matching distribution")):
                    self.skipTest("pip install not possible here: " + out[-400:])
                self.fail("pip install failed:\n" + out[-2000:])
            script = os.path.join(bindir, "stockroom.exe" if os.name == "nt" else "stockroom")
            self.assertTrue(os.path.exists(script), script)
            self.shop()
            shown = run([script, "stock", "--dir", self.dir], cwd=tmp)
            self.assertEqual(shown.returncode, 0, shown.stdout)
            self.assertEqual(shown.stdout.splitlines(), ["AB-100 17 ok Garden gnome",
                                                         "CD-205 40 low Seed packet, mix",
                                                         "EF-310 0 out Gift voucher"])
            neutral = run([py, "-c", "import stockroom, sys; print(stockroom.__file__)"], cwd=tmp)
            self.assertEqual(neutral.returncode, 0, neutral.stdout)
            self.assertNotIn(ROOT, neutral.stdout)

    def test_stdlib_only_and_python39_syntax(self):
        found = list(sources())
        self.assertTrue(found)
        for path in found:
            with open(path, "rb") as handle:
                text = handle.read().decode("utf-8")
            with self.subTest(path=os.path.relpath(path, ROOT)):
                tree = ast.parse(text, path, feature_version=(3, 9))
                compile(text, path, "exec")
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        names = [a.name for a in node.names]
                    elif isinstance(node, ast.ImportFrom) and node.level == 0:
                        names = [node.module]
                    else:
                        continue
                    for name in names:
                        top = name.split(".")[0]
                        self.assertTrue(top in STDLIB or top == "stockroom", "non-stdlib import: " + name)


if __name__ == "__main__":
    unittest.main()

