            venv = os.path.join(tmp, "venv")
            made = run([sys.executable, "-m", "venv", "--system-site-packages", venv])
            if made.returncode:
                self.skipTest("venv unavailable: " + made.stdout[-300:])
            bindir = os.path.join(venv, "Scripts" if os.name == "nt" else "bin")
            py = os.path.join(bindir, "python.exe" if os.name == "nt" else "python")
            probe = run([py, "-c", "import pip, setuptools"])
            if probe.returncode:
                self.skipTest("pip/setuptools unavailable in venv: " + probe.stdout[-300:])
            done = run([py, "-m", "pip", "install", "--no-build-isolation", "--no-index", "--disable-pip-version-check", repo])
            if done.returncode:
                out = done.stdout
                if any(s in out for s in ("No module named", "network", "Connection", "No matching distribution")):
                    self.skipTest("pip install not possible here: " + out[-400:])
                self.fail("pip install failed:\n" + out[-2000:])
            script = os.path.join(bindir, "stockroom.exe" if os.name == "nt" else "stockroom")
            self.assertTrue(os.path.exists(script), script)
            self.shop()
            shown = run([script, "stock", "--dir", self.dir], cwd=tmp)
            self.assertEqual(shown.returncode, 0, shown.stdout)
            self.assertEqual(shown.stdout.splitlines(), ["AB-100 17 ok Garden gnome",
                                                         "CD-205 40 low Seed packet, mix",
                                                         "EF-310 0 out Gift voucher"])
            neutral = run([py, "-c", "import stockroom, sys; print(stockroom.__file__)"], cwd=tmp)
            self.assertEqual(neutral.returncode, 0, neutral.stdout)
            self.assertNotIn(ROOT, neutral.stdout)

    def test_stdlib_only_and_python39_syntax(self):
        found = list(sources())
        self.assertTrue(found)
        for path in found:
            with open(path, "rb") as handle:
                text = handle.read().decode("utf-8")
            with self.subTest(path=os.path.relpath(path, ROOT)):
                tree = ast.parse(text, path, feature_version=(3, 9))
                compile(text, path, "exec")
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        names = [a.name for a in node.names]
                    elif isinstance(node, ast.ImportFrom) and node.level == 0:
                        names = [node.module]
                    else:
                        continue
                    for name in names:
                        top = name.split(".")[0]
                        self.assertTrue(top in STDLIB or top == "stockroom", "non-stdlib import: " + name)


